/* Sejdel homepage world globe.
 * Data + FX come from globe-cities.js (generated by the blog build).
 * globe.gl (three.js) is self-hosted and lazy-loaded only when the section
 * scrolls into view and only on capable devices. Reduced-motion / low-power /
 * no-WebGL fall back to a static night-earth map with the same dots + cards.
 * CSP: script-src 'self' — no inline handlers, no eval. */
(function () {
  "use strict";
  var section = document.getElementById("worldglobe");
  if (!section) return;
  var stage = section.querySelector(".globe-stage");
  var cardEl = section.querySelector(".globe-card");
  var resetBtn = section.querySelector(".globe-reset");
  var zinBtn = section.querySelector(".globe-zin");
  var zoutBtn = section.querySelector(".globe-zout");
  var curSel = section.querySelector(".globe-cur");
  var loadingEl = section.querySelector(".globe-loading");

  var CITIES = (window.SEJDEL_GLOBE_CITIES || []).slice();
  var FX = window.SEJDEL_FX || { USD: 1 };            // units of cur per 1 USD
  var reduce = matchMedia("(prefers-reduced-motion:reduce)").matches;
  var lowPower = (navigator.deviceMemory && navigator.deviceMemory <= 2) ||
    (matchMedia("(max-width:640px)").matches && (navigator.hardwareConcurrency || 8) <= 4);

  // ---- currency: from locale, overridable ----
  var REGION_CUR = { US:"USD",GB:"GBP",SE:"SEK",DE:"EUR",FR:"EUR",ES:"EUR",IT:"EUR",NL:"EUR",BE:"EUR",PT:"EUR",IE:"EUR",AT:"EUR",FI:"EUR",GR:"EUR",CH:"CHF",CA:"CAD",AU:"AUD",NZ:"NZD",TH:"THB",SG:"SGD",HK:"HKD",BR:"BRL",NO:"NOK",DK:"DKK",PL:"PLN",JP:"JPY",CN:"CNY",IN:"INR",MX:"MXN",ZA:"ZAR" };
  function detectCur() {
    try {
      var loc = new Intl.Locale(navigator.language);
      var reg = (loc.maximize && loc.maximize().region) || loc.region;
      if (reg && REGION_CUR[reg] && FX[REGION_CUR[reg]]) return REGION_CUR[reg];
    } catch (e) {}
    return "USD";
  }
  var userCur = detectCur();
  var SYM = { SEK:"kr", NOK:"kr", DKK:"kr", EUR:"€", GBP:"£", USD:"$", CHF:"CHF ", CAD:"$", AUD:"$", NZD:"$", THB:"฿", SGD:"S$", HKD:"HK$", BRL:"R$", JPY:"¥", PLN:"zł" };
  function money(v, c) {
    var noDec = (c === "SEK" || c === "NOK" || c === "DKK" || c === "JPY" || c === "HUF");
    var n = noDec ? Math.round(v) : Math.round(v * 100) / 100;
    var s = noDec ? String(n) : n.toFixed(2);
    var sym = SYM[c] || (c + " ");
    return (c === "SEK" || c === "NOK" || c === "DKK") ? n + " kr" : sym + s;
  }
  function convert(v, from, to) {
    if (from === to || !FX[from] || !FX[to]) return null;
    return v / FX[from] * FX[to];
  }
  // populate the override selector
  if (curSel) {
    ["USD","EUR","GBP","SEK","CHF","CAD","AUD","NOK","DKK"].forEach(function (c) {
      var o = document.createElement("option"); o.value = c; o.textContent = c;
      if (c === userCur) o.selected = true; curSel.appendChild(o);
    });
    if (["USD","EUR","GBP","SEK","CHF","CAD","AUD","NOK","DKK"].indexOf(userCur) < 0) {
      var o = document.createElement("option"); o.value = userCur; o.textContent = userCur; o.selected = true; curSel.appendChild(o);
    }
    curSel.addEventListener("change", function () { userCur = curSel.value; if (activeCity) showCard(activeCity); });
  }

  function cardHTML(c) {
    var cvt = convert(c.med, c.cur, userCur);
    var conv = cvt != null ? '<div class="gc-conv">≈ ' + money(cvt, userCur) + ' in your currency <span class="gc-approx">(approx)</span></div>' : "";
    return '<div class="gc-city">' + c.city + '</div><div class="gc-ctry">' + c.country + '</div>' +
      '<div class="gc-price">' + money(c.med, c.cur) + '</div><div class="gc-meta">median pint · ' + c.cur + '</div>' +
      conv + '<div class="gc-bars">' + c.bars + ' bars tracked</div>' +
      '<a class="gc-go" href="' + c.url + '">Read the guide →</a>';
  }

  var activeCity = null, globe = null, disposed = false, scTimer = null, scIdx = -1, lastTouch = 0;

  // ============ static fallback (reduced-motion / low-power / no WebGL) ============
  function renderStatic() {
    if (loadingEl) loadingEl.remove();
    stage.classList.add("is-static");
    var img = document.createElement("img");
    img.className = "globe-flat"; img.src = "./media/earth-night.jpg";
    img.alt = "A night-time world map with a glowing marker on every city Sejdel has a beer-price guide for.";
    img.decoding = "async"; img.loading = "lazy";
    stage.appendChild(img);
    var layer = document.createElement("div"); layer.className = "globe-flatpins";
    CITIES.forEach(function (c) {
      var a = document.createElement("a");
      a.className = "flatpin" + (c.home ? " home" : "");
      a.href = c.url; a.setAttribute("role", "link");
      a.setAttribute("aria-label", c.city + ", " + c.country + ". Median pint " + money(c.med, c.cur) + ". Read the price guide.");
      a.style.left = ((c.lon + 180) / 360 * 100).toFixed(2) + "%";
      a.style.top = ((90 - c.lat) / 180 * 100).toFixed(2) + "%";
      a.innerHTML = "<i></i>";
      a.addEventListener("mouseenter", function () { showCardAt(c, a); });
      a.addEventListener("focus", function () { showCardAt(c, a); });
      a.addEventListener("mouseleave", hideCard);
      a.addEventListener("blur", hideCard);
      layer.appendChild(a);
    });
    stage.appendChild(layer);
    function showCardAt(c, el) {
      activeCity = c; cardEl.innerHTML = cardHTML(c); cardEl.classList.add("show");
      var r = el.getBoundingClientRect(), sr = stage.getBoundingClientRect();
      var x = r.left - sr.left + 16, y = r.top - sr.top - 6;
      if (x + 220 > sr.width) x = r.left - sr.left - 220;
      if (y < 6) y = 6; if (y + 170 > sr.height) y = sr.height - 176;
      cardEl.style.left = x + "px"; cardEl.style.top = y + "px";
    }
  }

  // ============ WebGL globe ============
  function webglOK() {
    try { var c = document.createElement("canvas"); return !!(window.WebGLRenderingContext && (c.getContext("webgl") || c.getContext("experimental-webgl"))); }
    catch (e) { return false; }
  }

  function placeCardAtLatLng(c) {
    if (!globe.getScreenCoords) return;
    var s = globe.getScreenCoords(c.lat, c.lng != null ? c.lng : c.lon, 0.01);
    if (!s) return;
    var sr = stage.getBoundingClientRect();
    var x = s.x + 16, y = s.y - 8;
    if (x + 220 > sr.width) x = s.x - 220;
    if (y < 6) y = 6; if (y + 176 > sr.height) y = sr.height - 178;
    cardEl.style.left = x + "px"; cardEl.style.top = y + "px";
  }
  function showCard(c) { activeCity = c; cardEl.innerHTML = cardHTML(c); placeCardAtLatLng(c); cardEl.classList.add("show"); }
  function hideCard() { if (!cardEl.matches(":hover")) { cardEl.classList.remove("show"); activeCity = null; } }

  function makePin(c) {
    var el = document.createElement("div");
    el.className = "gpin" + (c.home ? " home" : "");
    el.tabIndex = 0; el.setAttribute("role", "link");
    el.setAttribute("aria-label", c.city + ", " + c.country + ". Median pint " + money(c.med, c.cur) + ". Read the price guide.");
    el.innerHTML = "<i></i>"; c._el = el;
    function on() { lastTouch = Date.now(); el.classList.add("hot"); showCard(c); }
    function off() { el.classList.remove("hot"); hideCard(); }
    el.addEventListener("mouseenter", on);
    el.addEventListener("mouseleave", off);
    el.addEventListener("focus", on);
    el.addEventListener("blur", off);
    el.addEventListener("click", function () { location.href = c.url; });
    el.addEventListener("keydown", function (e) { if (e.key === "Enter") location.href = c.url; });
    return el;
  }

  function showcase() {
    if (disposed) return;
    if (Date.now() - lastTouch < 7000) { scTimer = setTimeout(showcase, 2000); return; }
    scIdx = (scIdx + 1) % CITIES.length;
    var c = CITIES[scIdx];
    globe.controls().autoRotate = false;
    globe.pointOfView({ lat: c.lat * 0.7, lng: (c.lng != null ? c.lng : c.lon), altitude: 1.9 }, 1400);
    scTimer = setTimeout(function () {
      if (disposed || Date.now() - lastTouch < 1400) { scTimer = setTimeout(showcase, 1500); return; }
      showCard(c); if (c._el) c._el.classList.add("hot");
      scTimer = setTimeout(function () {
        cardEl.classList.remove("show"); if (c._el) c._el.classList.remove("hot"); activeCity = null;
        if (!reduce && globe) globe.controls().autoRotate = true;
        scTimer = setTimeout(showcase, 900);
      }, 3200);
    }, 1500);
  }
  function stopShowcase() { lastTouch = Date.now(); clearTimeout(scTimer); }

  function zoom(f) {
    var p = globe.pointOfView();
    globe.pointOfView({ lat: p.lat, lng: p.lng, altitude: Math.max(0.55, Math.min(3.2, p.altitude * f)) }, 600);
    stopShowcase(); resetBtn.classList.add("show");
  }
  function worldView() {
    stopShowcase(); cardEl.classList.remove("show"); resetBtn.classList.remove("show"); activeCity = null;
    globe.pointOfView({ lat: 25, lng: 12, altitude: 2.5 }, 1100);
    setTimeout(function () { if (disposed) return; if (!reduce) globe.controls().autoRotate = true; scTimer = setTimeout(showcase, 3000); }, 1200);
  }

  function initGlobe() {
    if (disposed || typeof Globe === "undefined") { renderStatic(); return; }
    if (loadingEl) loadingEl.remove();
    globe = Globe()(stage)
      .globeImageUrl("./media/earth-night.jpg")
      .backgroundColor("rgba(0,0,0,0)")
      .showAtmosphere(true).atmosphereColor("#e8a84a").atmosphereAltitude(0.15)
      .htmlElementsData(CITIES).htmlElement(makePin).htmlAltitude(0.01)
      .htmlLat(function (d) { return d.lat; }).htmlLng(function (d) { return d.lon; })
      .width(stage.clientWidth).height(stage.clientHeight);
    globe.pointOfView({ lat: 35, lng: 12, altitude: 2.3 }, 0);
    var ctrl = globe.controls();
    ctrl.enableZoom = true; ctrl.autoRotate = !reduce; ctrl.autoRotateSpeed = 0.32;
    ctrl.minDistance = 155; ctrl.maxDistance = 520;
    ctrl.addEventListener("start", function () { stopShowcase(); resetBtn.classList.add("show"); ctrl.autoRotate = false; });
    if (zinBtn) zinBtn.addEventListener("click", function () { zoom(0.7); });
    if (zoutBtn) zoutBtn.addEventListener("click", function () { zoom(1.4); });
    stage.addEventListener("dblclick", function () { zoom(0.65); });
    resetBtn.addEventListener("click", worldView);
    cardEl.addEventListener("mouseleave", function () { cardEl.classList.remove("show"); activeCity = null; });
    ro = new ResizeObserver(function () { if (globe) globe.width(stage.clientWidth).height(stage.clientHeight); });
    ro.observe(stage);
    if (!reduce) scTimer = setTimeout(showcase, 2600);
  }

  // ---- lazy boot + dispose ----
  var ro = null, booted = false;
  function boot() {
    if (booted) return; booted = true;
    if (reduce || lowPower || !webglOK()) { renderStatic(); return; }
    if (typeof Globe !== "undefined") { initGlobe(); return; }
    var s = document.createElement("script");
    s.src = "./vendor/globe.gl.min.js"; s.defer = true;
    s.onload = initGlobe; s.onerror = renderStatic;
    document.head.appendChild(s);
  }
  function dispose() {
    disposed = true; clearTimeout(scTimer);
    if (ro) { ro.disconnect(); ro = null; }
    if (globe) {
      try { globe.pauseAnimation && globe.pauseAnimation(); } catch (e) {}
      try { var r = globe.renderer && globe.renderer(); if (r) { r.dispose(); r.forceContextLoss && r.forceContextLoss(); } } catch (e) {}
      try { while (stage.firstChild) stage.removeChild(stage.firstChild); } catch (e) {}
      globe = null;
    }
  }

  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) { if (e.isIntersecting) boot(); });
  }, { rootMargin: "500px 0px" });
  io.observe(section);
  window.addEventListener("pagehide", dispose);
})();
